action.command:
cd /app && python3 -c "
import chess, re
pgn=open('position.pgn').read()
fen=re.search(r'\[FEN \"(.+?)\"\]', pgn).group(1)
b=chess.Board(fen)
mates=[]
for m in b.legal_moves:
    b.push(m)
    if b.is_checkmate(): mates.append(b.pop().__str__())
    else: b.pop()
print('mate moves:', mates)
for s in ['Re8#','Re8']:
    try:
        print(s, b.parse_san(s))
    except Exception as e:
        print(s,'ERR',e)
"

